files.content:
:root {
  --bg: #fffaf3;
  --text: #2b2118;
  --muted: #6b5a4a;
  --accent: #b5651d;
  --card: #ffffff;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid #ecdcc8;
}

.brand { font-weight: 700; font-size: 1.25rem; color: var(--accent); text-decoration: none; }

.site-nav ul { display: flex; gap: 1.25rem; list-style: none; margin: 0; padding: 0; }
.site-nav a { color: var(--text); text-decoration: none; }
.site-nav a[aria-current="page"] { color: var(--accent); font-weight: 600; }

main { max-width: 960px; margin: 0 auto; padding: 2rem 1.5rem; }

.hero h1 { font-size: 2rem; margin: 0 0 .5rem; }
.hero p, .page p { color: var(--muted); }

.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 1rem; list-style: none; padding: 0; }
.card { background: var(--card); border-radius: var(--radius); padding: 1rem 1.25rem; box-shadow: 0 1px 3px rgba(0, 0, 0, .08); }
.card h3 { margin: 0 0 .25rem; }

.site-footer { text-align: center; padding: 1.5rem; color: var(--muted); font-size: .9rem; border-top: 1px solid #ecdcc8; }

.contact-form { display: flex; flex-direction: column; gap: 1rem; margin-top: 1.5rem; max-width: 500px; }
.form-group { display: flex; flex-direction: column; gap: 0.35rem; }
.form-group label { font-weight: 600; font-size: 0.95rem; }
.form-group input, .form-group textarea { padding: 0.75rem; border: 1px solid #ecdcc8; border-radius: var(--radius); background: var(--card); font-family: inherit; font-size: 1rem; color: var(--text); }
.form-group input:focus, .form-group textarea:focus { outline: 2px solid var(--accent); }
.btn-submit { background: var(--accent); color: white; border: none; padding: 0.75rem 1.5rem; font-size: 1rem; font-weight: 600; border-radius: var(--radius); cursor: pointer; align-self: flex-start; }
.btn-submit:hover { opacity: 0.9; }
